# More famous Welsh people, part D: music, stage and screen, and sport.
# Same format and voice as people2a.py.
from people2a import P

PEOPLE = [
 P("ivor-novello", "modern", "1893–1951", "Ivor Novello", "Ivor Novello", "Songwriter and star", "Cyfansoddwr a seren", "Ivor_Novello", "music",
   "Cardiff-born composer of ‘Keep the Home Fires Burning’, matinee idol and the king of the musical stage. The Ivor Novello Awards bear his name.",
   "Cyfansoddwr ‘Keep the Home Fires Burning’ a aned yng Nghaerdydd, eilun y llwyfan a brenin y sioe gerdd. Mae Gwobrau Ivor Novello yn dwyn ei enw.",
   ["David Ivor Davies was born in Cardiff in 1893, the son of a famous singing teacher, Clara Novello Davies, who ran the Welsh Ladies’ Choir. He wrote ‘Keep the Home Fires Burning’ in 1914, and it became the song of the First World War.",
    "He became a film star, Britain’s greatest matinee idol, and wrote and starred in a string of romantic musicals such as Glamorous Night and The Dancing Years. The Ivor Novello Awards for songwriting are named in his honour, and his statue stands in Cardiff Bay."],
   ["Ganed David Ivor Davies yng Nghaerdydd yn 1893, yn fab i athrawes ganu enwog, Clara Novello Davies, a arweiniai Gôr Merched Cymru. Ysgrifennodd ‘Keep the Home Fires Burning’ yn 1914, a daeth yn gân y Rhyfel Byd Cyntaf.",
    "Daeth yn seren ffilm, eilun mwyaf llwyfan Prydain, ac ysgrifennu a serennu mewn cyfres o sioeau cerdd rhamantus fel Glamorous Night a The Dancing Years. Enwyd Gwobrau Ivor Novello am gyfansoddi caneuon er anrhydedd iddo, ac mae ei gerflun ym Mae Caerdydd."]),
 P("grace-williams", "modern", "1906–1977", "Grace Williams", "Grace Williams", "Composer of the sea", "Cyfansoddwraig y môr", "Grace_Williams", "music",
   "Barry composer of Sea Sketches and Fantasia on Welsh Nursery Tunes, the first woman in Britain to score a feature film.",
   "Cyfansoddwraig o’r Barri, awdur Sea Sketches a Fantasia on Welsh Nursery Tunes, y fenyw gyntaf ym Mhrydain i ysgrifennu cerddoriaeth ffilm hir.",
   ["Grace Williams was born in Barry in 1906, the daughter of two teachers, and grew up looking out over the Bristol Channel. She studied at Cardiff, London and Vienna, and returned to Barry to compose.",
    "Her Fantasia on Welsh Nursery Tunes and Sea Sketches are among the best loved Welsh orchestral works, and her opera The Parlour was staged by Welsh National Opera. In 1949 she wrote the music for the film Blue Scar, about a mining family, the first woman in Britain to score a feature film."],
   ["Ganed Grace Williams yn y Barri yn 1906, yn ferch i ddau athro, a’i magu’n edrych dros Fôr Hafren. Astudiodd yng Nghaerdydd, Llundain a Fienna, a dychwelyd i’r Barri i gyfansoddi.",
    "Mae ei Fantasia on Welsh Nursery Tunes a’i Sea Sketches ymhlith gweithiau cerddorfaol mwyaf annwyl Cymru, a llwyfannwyd ei hopera The Parlour gan Opera Cenedlaethol Cymru. Yn 1949 ysgrifennodd y gerddoriaeth i’r ffilm Blue Scar, am deulu o lowyr, y fenyw gyntaf ym Mhrydain i ysgrifennu cerddoriaeth ffilm hir."],
   first=("wales", "The first woman in Britain to write the score for a feature film, 1949", "Y fenyw gyntaf ym Mhrydain i ysgrifennu cerddoriaeth ffilm hir, 1949", 1949)),
 P("geraint-evans", "modern", "1922–1992", "Sir Geraint Evans", "Syr Geraint Evans", "The great Figaro", "Y Figaro mawr", "Geraint_Evans", "music",
   "Bass-baritone from Cilfynydd, one of the greatest opera singers of his age, famous for Figaro and Falstaff.",
   "Bas-bariton o Gilfynydd, un o gantorion opera mwyaf ei oes, yn enwog am Figaro a Falstaff.",
   ["Geraint Evans was born in Cilfynydd near Pontypridd, a miner’s son, and sang in the chapel before he trained in Hamburg and Geneva. He joined the Royal Opera House in 1948 and sang there for thirty-six years.",
    "His Figaro in Mozart’s Marriage of Figaro and his Falstaff in Verdi’s opera were famous from La Scala to the Metropolitan Opera in New York. He was the voice of a valley village that gave the world a star."],
   ["Ganed Geraint Evans yng Nghilfynydd ger Pontypridd, yn fab i löwr, a chanodd yn y capel cyn hyfforddi yn Hamburg a Genefa. Ymunodd â’r Tŷ Opera Brenhinol yn 1948 a chanu yno am un mlynedd ar bymtheg ar hugain.",
    "Roedd ei Figaro ym Mhriodas Figaro Mozart a’i Falstaff yn opera Verdi’n enwog o La Scala i’r Metropolitan Opera yn Efrog Newydd. Llais pentref yn y cymoedd a roddodd seren i’r byd."]),
 P("dafydd-iwan", "modern", "born 1943", "Dafydd Iwan", "Dafydd Iwan", "Singer of Yma o Hyd", "Canwr Yma o Hyd", "Dafydd_Iwan", "music",
   "Singer and campaigner from Brynaman whose song Yma o Hyd, ‘still here’, became the anthem of the Wales football team in 2022.",
   "Canwr ac ymgyrchydd o Frynaman y daeth ei gân Yma o Hyd yn anthem tîm pêl-droed Cymru yn 2022.",
   ["Dafydd Iwan was born in Brynaman, the son of a minister, and grew up in Llanuwchllyn. In the 1960s he became the voice of the language movement, chairman of Cymdeithas yr Iaith Gymraeg, and was jailed for refusing to pay fines for painting out English-only road signs.",
    "His songs, among them ‘Carlo’, ‘Pam fod eira’n wyn’ and ‘Yma o Hyd’, have been sung by every generation since. He founded the Sain record label and was president of Plaid Cymru. In 2022 the Wales football team adopted Yma o Hyd, and he sang it with them and the fans at the World Cup."],
   ["Ganed Dafydd Iwan ym Mrynaman, yn fab i weinidog, a’i fagu yn Llanuwchllyn. Yn y 1960au daeth yn llais mudiad yr iaith, yn gadeirydd Cymdeithas yr Iaith Gymraeg, a charcharwyd ef am wrthod talu dirwyon am beintio dros arwyddion ffyrdd uniaith Saesneg.",
    "Mae ei ganeuon, yn eu plith ‘Carlo’, ‘Pam fod eira’n wyn’ ac ‘Yma o Hyd’, wedi’u canu gan bob cenhedlaeth ers hynny. Sefydlodd gwmni recordiau Sain a bu’n llywydd Plaid Cymru. Yn 2022 mabwysiadodd tîm pêl-droed Cymru Yma o Hyd, a chanodd hi gyda hwy a’r cefnogwyr yng Nghwpan y Byd."]),
 P("meic-stevens", "modern", "born 1942", "Meic Stevens", "Meic Stevens", "The Welsh Dylan", "Y Dylan Cymraeg", "Meic_Stevens", "music",
   "Singer-songwriter from Solva, father of Welsh-language rock and folk, author of ‘Y Brawd Houdini’ and ‘Cân Walter’.",
   "Canwr-gyfansoddwr o Solfach, tad canu roc a gwerin Cymraeg, awdur ‘Y Brawd Houdini’ a ‘Cân Walter’.",
   ["Meic Stevens was born in Solva in Pembrokeshire and was raised by his grandparents. He played in the folk clubs of Manchester and London in the 1960s before coming home to sing in Welsh.",
    "His songs, among them ‘Y Brawd Houdini’, ‘Cân Walter’, ‘Môr o Gariad’ and ‘Erwan’, made modern Welsh music, and he has recorded more than thirty albums. He is often called the Welsh Bob Dylan."],
   ["Ganed Meic Stevens yn Solfach yn Sir Benfro a’i fagu gan ei nain a’i daid. Canodd yng nghlybiau gwerin Manceinion a Llundain yn y 1960au cyn dod adref i ganu yn Gymraeg.",
    "Gwnaeth ei ganeuon, yn eu plith ‘Y Brawd Houdini’, ‘Cân Walter’, ‘Môr o Gariad’ ac ‘Erwan’, gerddoriaeth Gymraeg fodern, ac mae wedi recordio dros ddeg ar hugain o albymau. Fe’i gelwir yn aml yn Bob Dylan Cymru."]),
 P("john-cale", "modern", "born 1942", "John Cale", "John Cale", "Founder of the Velvet Underground", "Sylfaenydd y Velvet Underground", "John_Cale", "music",
   "Welsh-speaking musician from Garnant who co-founded the Velvet Underground in New York and changed rock music.",
   "Cerddor Cymraeg o’r Garnant a gyd-sefydlodd y Velvet Underground yn Efrog Newydd ac a newidiodd gerddoriaeth roc.",
   ["John Cale was born in Garnant in the Amman valley in 1942 and spoke only Welsh until he went to school. A gifted viola player, he won a scholarship to study in the United States and joined the avant-garde in New York.",
    "In 1965 he founded the Velvet Underground with Lou Reed. Their records, with his droning viola, influenced generations of musicians. He went on to a long solo career, produced records for Patti Smith and the Stooges, and in 2009 represented Wales at the Venice Biennale."],
   ["Ganed John Cale yn y Garnant yn nyffryn Aman yn 1942 a Chymraeg yn unig a siaradai nes iddo fynd i’r ysgol. Yn chwaraewr fiola dawnus, enillodd ysgoloriaeth i astudio yn yr Unol Daleithiau ac ymuno â’r avant-garde yn Efrog Newydd.",
    "Yn 1965 sefydlodd y Velvet Underground gyda Lou Reed. Dylanwadodd eu recordiau, gyda’i fiola ef yn grwnan, ar genedlaethau o gerddorion. Aeth ymlaen i yrfa hir ar ei ben ei hun, cynhyrchu recordiau i Patti Smith a’r Stooges, ac yn 2009 cynrychioli Cymru yn Biennale Fenis."]),
 P("karl-jenkins", "today", "born 1944", "Sir Karl Jenkins", "Syr Karl Jenkins", "Composer of The Armed Man", "Cyfansoddwr The Armed Man", "Karl_Jenkins", "music",
   "Composer from Penclawdd on Gower whose mass The Armed Man is one of the most performed works by any living composer.",
   "Cyfansoddwr o Benclawdd ar Benrhyn Gŵyr y mae ei offeren The Armed Man yn un o’r gweithiau a berfformir amlaf gan unrhyw gyfansoddwr byw.",
   ["Karl Jenkins was born in Penclawdd in 1944, where his father was the chapel organist. He played jazz and rock with the band Soft Machine before turning to composing, and his Adiemus brought choral music to millions.",
    "His mass for peace, The Armed Man, was first performed in 2000 and has been sung thousands of times in dozens of countries. He has written music for the Senedd, for royal occasions and for Wales, and was knighted in 2015."],
   ["Ganed Karl Jenkins ym Mhenclawdd yn 1944, lle roedd ei dad yn organydd y capel. Chwaraeodd jazz a roc gyda’r band Soft Machine cyn troi at gyfansoddi, a daeth ei Adiemus â cherddoriaeth gorawl i filiynau.",
    "Perfformiwyd ei offeren dros heddwch, The Armed Man, gyntaf yn 2000 ac fe’i canwyd filoedd o weithiau mewn dwsinau o wledydd. Mae wedi ysgrifennu cerddoriaeth i’r Senedd, i achlysuron brenhinol ac i Gymru, ac fe’i hurddwyd yn farchog yn 2015."]),
 P("mary-hopkin", "modern", "born 1950", "Mary Hopkin", "Mary Hopkin", "Those were the days", "Those were the days", "Mary_Hopkin", "music",
   "Folk singer from Pontardawe who sang in Welsh before Paul McCartney signed her, and whose ‘Those Were the Days’ topped the charts in 1968.",
   "Cantores werin o Bontardawe a ganai yn Gymraeg cyn i Paul McCartney ei harwyddo, ac aeth ei ‘Those Were the Days’ i frig y siartiau yn 1968.",
   ["Mary Hopkin was born in Pontardawe in 1950 and grew up singing in chapel and recording Welsh-language folk songs. When she won the television talent show Opportunity Knocks, the model Twiggy told Paul McCartney about her.",
    "He signed her to the Beatles’ Apple label, and her first single, ‘Those Were the Days’, went to number one in Britain in 1968 and sold millions around the world. She represented the United Kingdom at the Eurovision Song Contest in 1970, and has kept singing in Welsh."],
   ["Ganed Mary Hopkin ym Mhontardawe yn 1950 a thyfodd i fyny’n canu yn y capel ac yn recordio caneuon gwerin Cymraeg. Pan enillodd y sioe dalent deledu Opportunity Knocks, soniodd y fodel Twiggy amdani wrth Paul McCartney.",
    "Arwyddodd hi i label Apple y Beatles, ac aeth ei sengl gyntaf, ‘Those Were the Days’, i rif un ym Mhrydain yn 1968 a gwerthu miliynau ledled y byd. Cynrychiolodd y Deyrnas Unedig yng Nghystadleuaeth Cân Eurovision yn 1970, ac mae wedi dal ati i ganu yn Gymraeg."]),
 P("bonnie-tyler", "modern", "born 1951", "Bonnie Tyler", "Bonnie Tyler", "Total Eclipse of the Heart", "Total Eclipse of the Heart", "Bonnie_Tyler", "music",
   "Singer from Skewen with the famous husky voice, whose ‘Total Eclipse of the Heart’ was number one in Britain and America in 1983.",
   "Cantores o Sgiwen â’r llais cryg enwog, yr aeth ei ‘Total Eclipse of the Heart’ i rif un ym Mhrydain ac America yn 1983.",
   ["Gaynor Hopkins was born in Skewen near Neath in 1951 and started singing in the pubs and clubs of south Wales. As Bonnie Tyler she had her first big hit with ‘It’s a Heartache’ in 1977.",
    "In 1983 ‘Total Eclipse of the Heart’ went to number one in Britain, the United States and many other countries, and has sold millions of copies. ‘Holding Out for a Hero’ followed. She represented the United Kingdom at Eurovision in 2013."],
   ["Ganed Gaynor Hopkins yn Sgiwen ger Castell-nedd yn 1951 a dechreuodd ganu yn nhafarnau a chlybiau’r de. Fel Bonnie Tyler cafodd ei llwyddiant mawr cyntaf gyda ‘It’s a Heartache’ yn 1977.",
    "Yn 1983 aeth ‘Total Eclipse of the Heart’ i rif un ym Mhrydain, yr Unol Daleithiau a llawer o wledydd eraill, a gwerthu miliynau o gopïau. Dilynodd ‘Holding Out for a Hero’. Cynrychiolodd y Deyrnas Unedig yn Eurovision yn 2013."]),
 P("bryn-terfel", "modern", "born 1965", "Sir Bryn Terfel", "Syr Bryn Terfel", "The farmer’s son who sang to the world", "Mab y fferm a ganodd i’r byd", "Bryn_Terfel", "music",
   "Bass-baritone from Pant Glas in Eifionydd, one of the great opera singers of the world, who never left the Eisteddfod behind.",
   "Bas-bariton o Bant Glas yn Eifionydd, un o gantorion opera mawr y byd, nad anghofiodd yr Eisteddfod erioed.",
   ["Bryn Terfel Jones was born on a farm at Pant Glas near Garndolbenmaen in 1965 and learned to sing at eisteddfodau. In 1989 he won the Lieder Prize at Cardiff Singer of the World, and within a few years he was singing at the great opera houses of the world.",
    "His Figaro, his Falstaff and his Wotan in Wagner’s Ring have been acclaimed in New York, London, Vienna and Milan, and he has won Grammy awards. He has sung at royal weddings and great occasions, founded the Faenol festival and always records in Welsh."],
   ["Ganed Bryn Terfel Jones ar fferm ym Mhant Glas ger Garndolbenmaen yn 1965 a dysgodd ganu yn yr eisteddfodau. Yn 1989 enillodd Wobr y Lieder yng nghystadleuaeth Canwr y Byd Caerdydd, ac o fewn ychydig flynyddoedd roedd yn canu yn nhai opera mawr y byd.",
    "Mae ei Figaro, ei Falstaff a’i Wotan yng Nghylch Wagner wedi’u canmol yn Efrog Newydd, Llundain, Fienna a Milan, ac mae wedi ennill gwobrau Grammy. Mae wedi canu mewn priodasau brenhinol ac achlysuron mawr, sefydlu gŵyl y Faenol ac mae bob amser yn recordio yn Gymraeg."]),
 P("cerys-matthews", "today", "born 1969", "Cerys Matthews", "Cerys Matthews", "International Velvet", "International Velvet", "Cerys_Matthews", "music",
   "Singer of Catatonia, whose anthem ‘International Velvet’ gave Wales the line ‘Every day when I wake up, I thank the Lord I’m Welsh’.",
   "Cantores Catatonia, a roddodd ei hanthem ‘International Velvet’ y llinell ‘Every day when I wake up, I thank the Lord I’m Welsh’ i Gymru.",
   ["Cerys Matthews was born in Cardiff in 1969 and grew up in Swansea and Pembrokeshire. With the band Catatonia she became one of the stars of the Cool Cymru years of the late 1990s, with hits such as ‘Mulder and Scully’ and ‘Road Rage’.",
    "Their song ‘International Velvet’, in Welsh and English, became an anthem of the new, confident Wales of devolution. She has gone on to record folk songs, write books for children and present on BBC radio, and founded the Good Life Experience festival."],
   ["Ganed Cerys Matthews yng Nghaerdydd yn 1969 a’i magu yn Abertawe a Sir Benfro. Gyda’r band Catatonia daeth yn un o sêr blynyddoedd Cŵl Cymru ddiwedd y 1990au, gyda chaneuon fel ‘Mulder and Scully’ a ‘Road Rage’.",
    "Daeth eu cân ‘International Velvet’, yn Gymraeg ac yn Saesneg, yn anthem Cymru newydd, hyderus datganoli. Aeth ymlaen i recordio caneuon gwerin, ysgrifennu llyfrau i blant a chyflwyno ar radio’r BBC."]),
 P("katherine-jenkins", "today", "born 1980", "Katherine Jenkins", "Katherine Jenkins", "The voice of Neath", "Llais Castell-nedd", "Katherine_Jenkins", "music",
   "Mezzo-soprano from Neath, the best-selling classical singer of her generation, who sings Welsh hymns to stadiums.",
   "Mezzo-soprano o Gastell-nedd, cantores glasurol fwyaf poblogaidd ei chenhedlaeth, sy’n canu emynau Cymraeg i stadia.",
   ["Katherine Jenkins was born in Neath in 1980 and sang in the choir of Llandaf Cathedral and in the National Youth Choir of Wales. Her first album, in 2004, went straight to the top of the classical charts.",
    "She has sold millions of albums, sung before rugby internationals at the Principality Stadium, at royal occasions and for troops overseas, and always included Welsh songs such as ‘Calon Lân’ and ‘Ar Lan y Môr’."],
   ["Ganed Katherine Jenkins yng Nghastell-nedd yn 1980 a chanodd yng nghôr Eglwys Gadeiriol Llandaf ac yng Nghôr Cenedlaethol Ieuenctid Cymru. Aeth ei halbwm cyntaf, yn 2004, yn syth i frig y siartiau clasurol.",
    "Mae wedi gwerthu miliynau o albymau, canu cyn gemau rygbi rhyngwladol yn Stadiwm Principality, mewn achlysuron brenhinol ac i filwyr dramor, a chynnwys caneuon Cymraeg fel ‘Calon Lân’ ac ‘Ar Lan y Môr’ bob tro."]),
 P("ray-milland", "modern", "1907–1986", "Ray Milland", "Ray Milland", "The first Welsh Oscar winner", "Enillydd Oscar cyntaf Cymru", "Ray_Milland", "stage",
   "Born Alfred Jones in Neath, a Hollywood star who in 1946 became the first Welsh actor to win an Oscar.",
   "Ganed yn Alfred Jones yng Nghastell-nedd; seren Hollywood a ddaeth, yn 1946, yr actor cyntaf o Gymru i ennill Oscar.",
   ["Alfred Reginald Jones was born in Neath in 1907. He served in the Household Cavalry before trying his luck in films in London and then in Hollywood, taking the name Ray Milland.",
    "He made more than a hundred and fifty films, among them Dial M for Murder for Alfred Hitchcock. For his part in The Lost Weekend he won the Academy Award for Best Actor in 1946, the first Welsh actor to win an Oscar."],
   ["Ganed Alfred Reginald Jones yng Nghastell-nedd yn 1907. Gwasanaethodd yn y Household Cavalry cyn mentro i ffilmiau yn Llundain ac yna yn Hollywood, gan gymryd yr enw Ray Milland.",
    "Gwnaeth dros gant a hanner o ffilmiau, yn eu plith Dial M for Murder i Alfred Hitchcock. Am ei ran yn The Lost Weekend enillodd Wobr yr Academi am yr Actor Gorau yn 1946, yr actor cyntaf o Gymru i ennill Oscar."],
   first=("wales", "The first Welsh actor to win an Oscar, 1946", "Yr actor cyntaf o Gymru i ennill Oscar, 1946", 1946)),
 P("hugh-griffith", "modern", "1912–1980", "Hugh Griffith", "Hugh Griffith", "Oscar winner from Môn", "Enillydd Oscar o Fôn", "Hugh_Griffith", "stage",
   "Welsh-speaking actor from Marian-glas in Môn who won an Oscar for Ben-Hur.",
   "Actor Cymraeg o Farian-glas ym Môn a enillodd Oscar am Ben-Hur.",
   ["Hugh Griffith was born at Marian-glas in Anglesey in 1912 and worked as a bank clerk before going on the stage. He became a great Shakespearean actor, famous for his bushy eyebrows and booming voice.",
    "For playing the sheikh in Ben-Hur he won the Academy Award for Best Supporting Actor in 1960. He also starred in Tom Jones and Oliver!, acted in Welsh on radio and stage, and was proud of Môn all his life."],
   ["Ganed Hugh Griffith ym Marian-glas ym Môn yn 1912 a bu’n glerc banc cyn mynd ar y llwyfan. Daeth yn actor Shakespearaidd mawr, yn enwog am ei aeliau trwchus a’i lais mawr.",
    "Am chwarae’r sheikh yn Ben-Hur enillodd Wobr yr Academi am yr Actor Cynorthwyol Gorau yn 1960. Bu hefyd yn serennu yn Tom Jones ac Oliver!, actio yn Gymraeg ar y radio a’r llwyfan, ac roedd yn falch o Fôn ar hyd ei oes."]),
 P("harry-secombe", "modern", "1921–2001", "Sir Harry Secombe", "Syr Harry Secombe", "The Goon with the golden voice", "Y Goon â’r llais aur", "Harry_Secombe", "stage",
   "Swansea comedian and tenor of The Goon Show, who also starred as Mr Bumble in Oliver! and presented Highway.",
   "Digrifwr a thenor o Abertawe yn The Goon Show, a fu hefyd yn serennu fel Mr Bumble yn Oliver! ac yn cyflwyno Highway.",
   ["Harry Secombe was born in St Thomas, Swansea, in 1921. He served in the Royal Artillery in North Africa and Italy, where he met Spike Milligan, and after the war he worked as a comedian.",
    "With Milligan, Peter Sellers and Michael Bentine he made The Goon Show, the radio comedy that changed British humour. He was also a fine tenor, starred as Mr Bumble in the film Oliver! and presented the Sunday hymn programme Highway for many years."],
   ["Ganed Harry Secombe yn St Thomas, Abertawe, yn 1921. Gwasanaethodd yn y Magnelwyr Brenhinol yng Ngogledd Affrica a’r Eidal, lle cyfarfu â Spike Milligan, ac wedi’r rhyfel gweithiodd yn ddigrifwr.",
    "Gyda Milligan, Peter Sellers a Michael Bentine gwnaeth The Goon Show, y gomedi radio a newidiodd hiwmor Prydain. Roedd hefyd yn denor gwych, serennodd fel Mr Bumble yn y ffilm Oliver! a chyflwynodd y rhaglen emynau Highway am flynyddoedd lawer."]),
 P("sian-phillips", "modern", "born 1933", "Dame Siân Phillips", "Y Fonesig Siân Phillips", "Grande dame of Gwaun-cae-Gurwen", "Grande dame Gwaun-cae-Gurwen", "Siân_Phillips", "stage",
   "Welsh-speaking actor from Gwaun-cae-Gurwen, unforgettable as Livia in I, Claudius, who has acted on stage and screen for seventy years.",
   "Actores Gymraeg o Waun-cae-Gurwen, bythgofiadwy fel Livia yn I, Claudius, sydd wedi actio ar lwyfan a sgrin am ddeng mlynedd a thrigain.",
   ["Siân Phillips was born at Gwaun-cae-Gurwen in 1933 and began broadcasting in Welsh for the BBC as a child. She trained at RADA and became one of the great actors of the British stage.",
    "Her Livia in the television series I, Claudius in 1976 is one of the most celebrated performances in television history. She has appeared in Dune, Tinker Tailor Soldier Spy and countless plays and musicals, and has kept working into her nineties."],
   ["Ganed Siân Phillips yng Ngwaun-cae-Gurwen yn 1933 a dechreuodd ddarlledu yn Gymraeg i’r BBC yn blentyn. Hyfforddodd yn RADA a daeth yn un o actorion mawr llwyfan Prydain.",
    "Mae ei Livia yn y gyfres deledu I, Claudius yn 1976 yn un o berfformiadau enwocaf hanes teledu. Mae wedi ymddangos yn Dune, Tinker Tailor Soldier Spy a dramâu a sioeau cerdd dirifedi, ac mae wedi dal ati i weithio yn ei nawdegau."]),
 P("ryan-davies", "modern", "1937–1977", "Ryan Davies", "Ryan Davies", "Ryan of Ryan a Ronnie", "Ryan o Ryan a Ronnie", "Ryan_Davies", "stage",
   "Comedian, singer and actor from Glanaman, half of the double act Ryan a Ronnie and the best loved entertainer in Welsh.",
   "Digrifwr, canwr ac actor o Lanaman, hanner y ddeuawd Ryan a Ronnie a diddanwr mwyaf annwyl y Gymraeg.",
   ["Ryan Davies was born in Glanaman in 1937 and grew up in Llanfyllin. He trained as a teacher, then with Ronnie Williams formed Ryan a Ronnie, whose comedy shows on BBC Wales in Welsh and English had the whole country laughing.",
    "He was a gifted pianist and singer, and his song ‘Pan Fo’r Nos yn Hir’ is a classic. He played Second Voice in the 1972 film of Under Milk Wood alongside Richard Burton. He died young, at forty, and Wales mourned him."],
   ["Ganed Ryan Davies yng Nglanaman yn 1937 a’i fagu yn Llanfyllin. Hyfforddodd yn athro, yna gyda Ronnie Williams ffurfiodd Ryan a Ronnie, y cadwodd eu sioeau comedi ar BBC Cymru, yn Gymraeg ac yn Saesneg, y wlad gyfan yn chwerthin.",
    "Roedd yn bianydd a chanwr dawnus, ac mae ei gân ‘Pan Fo’r Nos yn Hir’ yn glasur. Chwaraeodd yr Ail Lais yn ffilm Under Milk Wood yn 1972 gyda Richard Burton. Bu farw’n ifanc, yn ddeugain oed, a galarodd Cymru amdano."]),
 P("max-boyce", "modern", "born 1943", "Max Boyce", "Max Boyce", "I was there", "Roeddwn i yno", "Max_Boyce", "stage",
   "Former miner from Glynneath whose songs and stories of rugby and the valleys made him a national hero in the golden 1970s.",
   "Cyn-löwr o Lyn-nedd y gwnaeth ei ganeuon a’i straeon am rygbi a’r cymoedd ef yn arwr cenedlaethol yn oes aur y 1970au.",
   ["Max Boyce was born in Glynneath in 1943 and worked underground as a miner and as an electrician. He began singing his own songs in rugby clubs, and his album Live at Treorchy, recorded in 1974, became a national treasure.",
    "Songs such as ‘Hymns and Arias’, ‘The Outside-Half Factory’ and ‘Duw, It’s Hard’ captured the pride of the valleys in the years Wales ruled the rugby world, and his giant leek and cry of ‘I was there!’ became part of every Welsh match day."],
   ["Ganed Max Boyce yng Nglyn-nedd yn 1943 a gweithiodd dan ddaear yn löwr ac yn drydanwr. Dechreuodd ganu ei ganeuon ei hun mewn clybiau rygbi, a daeth ei albwm Live at Treorchy, a recordiwyd yn 1974, yn drysor cenedlaethol.",
    "Daliodd caneuon fel ‘Hymns and Arias’, ‘The Outside-Half Factory’ a ‘Duw, It’s Hard’ falchder y cymoedd yn y blynyddoedd pan oedd Cymru’n rheoli byd rygbi, a daeth ei genhinen anferth a’i waedd ‘I was there!’ yn rhan o bob diwrnod gêm yng Nghymru."]),
 P("catherine-zeta-jones", "today", "born 1969", "Catherine Zeta-Jones", "Catherine Zeta-Jones", "Oscar winner from Swansea", "Enillydd Oscar o Abertawe", "Catherine_Zeta-Jones", "stage",
   "Swansea-born star of The Mask of Zorro and Chicago, who won an Oscar in 2003.",
   "Seren The Mask of Zorro a Chicago a aned yn Abertawe, ac a enillodd Oscar yn 2003.",
   ["Catherine Zeta-Jones was born in Swansea in 1969 and was dancing and singing on stage from childhood, starring in the West End musical 42nd Street as a teenager. She became famous in Britain in The Darling Buds of May.",
    "In Hollywood she starred in The Mask of Zorro, Entrapment and Traffic, and for her role as Velma Kelly in Chicago she won the Academy Award for Best Supporting Actress in 2003. She has also won a Tony award on Broadway, and often speaks of her pride in Swansea."],
   ["Ganed Catherine Zeta-Jones yn Abertawe yn 1969 a bu’n dawnsio a chanu ar lwyfan o’i phlentyndod, gan serennu yn y sioe gerdd 42nd Street yn y West End yn ei harddegau. Daeth yn enwog ym Mhrydain yn The Darling Buds of May.",
    "Yn Hollywood serennodd yn The Mask of Zorro, Entrapment a Traffic, ac am ei rhan fel Velma Kelly yn Chicago enillodd Wobr yr Academi am yr Actores Gynorthwyol Orau yn 2003. Mae hefyd wedi ennill gwobr Tony ar Broadway, ac mae’n sôn yn aml am ei balchder yn Abertawe."]),
 P("michael-sheen", "today", "born 1969", "Michael Sheen", "Michael Sheen", "Actor of Port Talbot", "Actor Port Talbot", "Michael_Sheen", "stage",
   "Actor from Port Talbot, star of The Queen and Frost/Nixon, who staged The Passion in his home town and paid off the debts of 900 people in Wales.",
   "Actor o Bort Talbot, seren The Queen a Frost/Nixon, a lwyfannodd The Passion yn ei dref enedigol ac a dalodd ddyledion 900 o bobl yng Nghymru.",
   ["Michael Sheen was born in Newport in 1969 and grew up in Port Talbot, where he acted with the West Glamorgan Youth Theatre before training at RADA. He became famous for playing real people, Tony Blair in The Queen and David Frost in Frost/Nixon among them.",
    "In 2011 he staged The Passion, a seventy-two-hour play acted through the streets and beaches of Port Talbot with a thousand local people. He gives much of his time and money to Wales: in 2024 he bought up and wrote off a million pounds of debt owed by some nine hundred people in south Wales."],
   ["Ganed Michael Sheen yng Nghasnewydd yn 1969 a’i fagu ym Mhort Talbot, lle bu’n actio gyda Theatr Ieuenctid Gorllewin Morgannwg cyn hyfforddi yn RADA. Daeth yn enwog am chwarae pobl go iawn, Tony Blair yn The Queen a David Frost yn Frost/Nixon yn eu plith.",
    "Yn 2011 llwyfannodd The Passion, drama dri diwrnod a chwaraewyd drwy strydoedd a thraethau Port Talbot gyda mil o bobl leol. Mae’n rhoi llawer o’i amser a’i arian i Gymru: yn 2024 prynodd a dileu miliwn o bunnoedd o ddyledion tua naw cant o bobl yn ne Cymru."]),
 P("ioan-gruffudd", "today", "born 1973", "Ioan Gruffudd", "Ioan Gruffudd", "From Pobol y Cwm to Hollywood", "O Pobol y Cwm i Hollywood", "Ioan_Gruffudd", "stage",
   "Welsh-speaking actor from Aberdare who went from Pobol y Cwm to Hornblower, Titanic and Fantastic Four.",
   "Actor Cymraeg o Aberdâr a aeth o Pobol y Cwm i Hornblower, Titanic a Fantastic Four.",
   ["Ioan Gruffudd was born in Aberdare in 1973, went to Ysgol Gyfun Rhydfelen and began acting on S4C’s Pobol y Cwm at the age of thirteen. He trained at RADA and made his name as Horatio Hornblower on television.",
    "He played the officer Harold Lowe in Titanic, Mister Fantastic in Fantastic Four, and many leading roles in film and television."],
   ["Ganed Ioan Gruffudd yn Aberdâr yn 1973, aeth i Ysgol Gyfun Rhydfelen a dechreuodd actio ar Pobol y Cwm ar S4C yn dair ar ddeg oed. Hyfforddodd yn RADA a gwnaeth ei enw fel Horatio Hornblower ar y teledu.",
    "Chwaraeodd y swyddog Harold Lowe yn Titanic, Mister Fantastic yn Fantastic Four, a llawer o brif rannau mewn ffilm a theledu."]),
 P("freddie-welsh", "modern", "1886–1927", "Freddie Welsh", "Freddie Welsh", "World lightweight champion", "Pencampwr pwysau ysgafn y byd", "Freddie_Welsh", "sport",
   "Boxer from Pontypridd who became lightweight champion of the world in 1914, and fought under a name that told everyone where he came from.",
   "Paffiwr o Bontypridd a ddaeth yn bencampwr pwysau ysgafn y byd yn 1914, ac a ymladdai dan enw a ddywedai wrth bawb o ble y deuai.",
   ["Frederick Hall Thomas was born in Pontypridd in 1886. He went to America as a teenager and learned to box in Philadelphia, fighting as Freddie Welsh so that no one would forget his country.",
    "He was a clever, scientific boxer who studied diet and fitness long before others did. On 7 July 1914 in London he beat Willie Ritchie to become lightweight champion of the world, and he held the title for three years."],
   ["Ganed Frederick Hall Thomas ym Mhontypridd yn 1886. Aeth i America yn ei arddegau a dysgu paffio yn Philadelphia, gan ymladd fel Freddie Welsh fel na fyddai neb yn anghofio’i wlad.",
    "Roedd yn baffiwr clyfar, gwyddonol, a astudiai fwyd a ffitrwydd ymhell cyn eraill. Ar 7 Gorffennaf 1914 yn Llundain curodd Willie Ritchie i ddod yn bencampwr pwysau ysgafn y byd, a daliodd y teitl am dair blynedd."]),
 P("jimmy-wilde", "modern", "1892–1969", "Jimmy Wilde", "Jimmy Wilde", "The Mighty Atom", "Yr Atom Nerthol", "Jimmy_Wilde", "sport",
   "Tiny miner from Tylorstown who became the first flyweight champion of the world in 1916, often called the greatest flyweight of all time.",
   "Glöwr bychan o Tylorstown a ddaeth yn bencampwr pwysau pry cyntaf y byd yn 1916, a elwir yn aml y pwysau pry gorau erioed.",
   ["Jimmy Wilde was born near Merthyr in 1892 and worked in the pits of Tylorstown in the Rhondda, where his small size let him work in the narrowest seams. He learned to box in fairground booths, taking on men far heavier than himself.",
    "Rarely weighing more than seven stone, he hit with astonishing power and was called the Mighty Atom and ‘the ghost with a hammer in his hand’. In December 1916 he became the first flyweight champion of the world, and boxing historians still rank him as the greatest flyweight ever."],
   ["Ganed Jimmy Wilde ger Merthyr yn 1892 a gweithiodd ym mhyllau Tylorstown yn y Rhondda, lle gadawai ei faint bychan iddo weithio yn y gwythiennau culaf. Dysgodd baffio ym mythau’r ffeiriau, yn ymladd dynion llawer trymach nag ef.",
    "Anaml y pwysai fwy na saith stôn, ond trawai â nerth rhyfeddol, a’i alw’n Atom Nerthol ac ‘ysbryd â morthwyl yn ei law’. Ym mis Rhagfyr 1916 daeth yn bencampwr pwysau pry cyntaf y byd, ac mae haneswyr paffio’n dal i’w gyfrif y pwysau pry gorau erioed."],
   first=("world", "The first flyweight boxing champion of the world, 1916", "Pencampwr paffio pwysau pry cyntaf y byd, 1916", 1916)),
 P("tommy-farr", "modern", "1913–1986", "Tommy Farr", "Tommy Farr", "The Tonypandy Terror", "Daeargryn Tonypandy", "Tommy_Farr", "sport",
   "Miner from Clydach Vale who went the full fifteen rounds with Joe Louis for the heavyweight championship of the world in 1937.",
   "Glöwr o Gwm Clydach a aeth y pymtheg rownd lawn gyda Joe Louis am bencampwriaeth pwysau trwm y byd yn 1937.",
   ["Tommy Farr was born in Clydach Vale in the Rhondda in 1913 and went down the pit at twelve. He learned to fight in the travelling boxing booths and became British heavyweight champion in 1937.",
    "In August 1937 at Yankee Stadium in New York he fought Joe Louis, one of the greatest heavyweights of all time, for the championship of the world. Farr went the full fifteen rounds and lost only on points, and people back home in the valleys sat up through the night around their wirelesses to listen."],
   ["Ganed Tommy Farr yng Nghwm Clydach yn y Rhondda yn 1913 ac aeth i lawr y pwll yn ddeuddeg oed. Dysgodd ymladd ym mythau paffio teithiol a daeth yn bencampwr pwysau trwm Prydain yn 1937.",
    "Ym mis Awst 1937 yn Stadiwm Yankee yn Efrog Newydd ymladdodd Joe Louis, un o’r pwysau trwm mwyaf erioed, am bencampwriaeth y byd. Aeth Farr y pymtheg rownd lawn a cholli ar bwyntiau’n unig, a bu pobl gartref yn y cymoedd ar eu traed drwy’r nos o gwmpas y radio’n gwrando."]),
 P("ray-reardon", "modern", "1932–2024", "Ray Reardon", "Ray Reardon", "Dracula of the baize", "Dracula’r bwrdd gwyrdd", "Ray_Reardon", "sport",
   "Former miner from Tredegar who won the World Snooker Championship six times in the 1970s.",
   "Cyn-löwr o Dredegar a enillodd Bencampwriaeth Snwcer y Byd chwe gwaith yn y 1970au.",
   ["Ray Reardon was born in Tredegar in 1932 and worked as a miner, then as a policeman, before turning professional at snooker. With his sharp widow’s peak and showman’s smile he was nicknamed Dracula.",
    "He won the World Championship six times, in 1970, 1973, 1974, 1975, 1976 and 1978, and was the leading player of the decade in which television made snooker one of the most watched sports in Britain."],
   ["Ganed Ray Reardon yn Nhredegar yn 1932 a gweithiodd yn löwr, yna’n heddwas, cyn troi’n broffesiynol mewn snwcer. Gyda’i wallt pigfain a gwên y sioewr cafodd y llysenw Dracula.",
    "Enillodd Bencampwriaeth y Byd chwe gwaith, yn 1970, 1973, 1974, 1975, 1976 a 1978, ac ef oedd prif chwaraewr y degawd pan wnaeth teledu snwcer yn un o’r campau a wyliwyd fwyaf ym Mhrydain."]),
 P("barry-john", "modern", "1945–2024", "Barry John", "Barry John", "The King", "Y Brenin", "Barry_John", "sport",
   "Fly-half from Cefneithin who was crowned ‘The King’ by New Zealand on the Lions’ winning tour of 1971.",
   "Maswr o Gefneithin a goronwyd yn ‘Frenin’ gan Seland Newydd ar daith fuddugol y Llewod yn 1971.",
   ["Barry John was born in Cefneithin in Carmarthenshire in 1945 and grew up watching Carwyn James play for the village. He became the fly-half of the great Wales team of the late 1960s and early 1970s, with Gareth Edwards at scrum-half.",
    "On the British and Irish Lions tour of New Zealand in 1971, the only Lions series ever won there, he scored a record 191 points and the New Zealand press called him ‘The King’. He retired at twenty-seven, at the height of his fame."],
   ["Ganed Barry John yng Nghefneithin yn Sir Gaerfyrddin yn 1945 a thyfodd i fyny’n gwylio Carwyn James yn chwarae i’r pentref. Daeth yn faswr tîm mawr Cymru ddiwedd y 1960au a dechrau’r 1970au, gyda Gareth Edwards yn fewnwr.",
    "Ar daith y Llewod i Seland Newydd yn 1971, yr unig gyfres i’r Llewod ei hennill yno erioed, sgoriodd record o 191 o bwyntiau a galwodd y wasg yn Seland Newydd ef yn ‘The King’. Ymddeolodd yn saith ar hugain, ar anterth ei enwogrwydd."]),
 P("lynn-davies", "modern", "born 1942", "Lynn Davies", "Lynn Davies", "Lynn the Leap", "Lynn y Naid", "Lynn_Davies", "sport",
   "Long jumper from Nant-y-moel who won Olympic gold in Tokyo in 1964.",
   "Neidiwr hir o Nant-y-moel a enillodd aur Olympaidd yn Tokyo yn 1964.",
   ["Lynn Davies was born in Nant-y-moel in the Ogmore valley in 1942, the son of a miner. He was a promising footballer before a coach spotted his speed and spring.",
    "At the Tokyo Olympics in 1964, in wind and rain, he jumped 8.07 metres to win the gold medal. He went on to win European and Commonwealth titles, and later became president of UK Athletics. Wales has called him Lynn the Leap ever since."],
   ["Ganed Lynn Davies yn Nant-y-moel yng Nghwm Ogwr yn 1942, yn fab i löwr. Roedd yn bêl-droediwr addawol cyn i hyfforddwr sylwi ar ei gyflymder a’i naid.",
    "Yng Ngemau Olympaidd Tokyo yn 1964, mewn gwynt a glaw, neidiodd 8.07 metr i ennill y fedal aur. Aeth ymlaen i ennill teitlau Ewrop a’r Gymanwlad, a daeth wedyn yn llywydd Athletau’r DU. Mae Cymru wedi’i alw’n Lynn the Leap fyth ers hynny."]),
 P("jpr-williams", "modern", "1949–2024", "J. P. R. Williams", "J. P. R. Williams", "The fearless full-back", "Y cefnwr di-ofn", "J._P._R._Williams", "sport",
   "Full-back of the golden era, three times a Grand Slam winner and twice a winning Lion, who was also a surgeon.",
   "Cefnwr yr oes aur, enillydd y Gamp Lawn deirgwaith a Llew buddugol ddwywaith, a oedd hefyd yn llawfeddyg.",
   ["John Peter Rhys Williams was born in Bridgend in 1949. As a boy he was a fine tennis player and won the junior title at Wimbledon in 1966, before choosing rugby.",
    "With his long sideburns and fearless tackling he became the most famous full-back in the world. He won three Grand Slams with Wales in the 1970s and was a key man for the Lions in their series wins in New Zealand in 1971 and South Africa in 1974. Off the field he was an orthopaedic surgeon."],
   ["Ganed John Peter Rhys Williams ym Mhen-y-bont ar Ogwr yn 1949. Yn fachgen roedd yn chwaraewr tennis gwych ac enillodd y teitl iau yn Wimbledon yn 1966, cyn dewis rygbi.",
    "Gyda’i locsys hir a’i daclo di-ofn daeth yn gefnwr enwocaf y byd. Enillodd dair Camp Lawn gyda Chymru yn y 1970au a bu’n allweddol i’r Llewod yn eu buddugoliaethau yn Seland Newydd yn 1971 a De Affrica yn 1974. Oddi ar y cae roedd yn llawfeddyg orthopedig."]),
 P("phil-bennett", "modern", "1948–2022", "Phil Bennett", "Phil Bennett", "The magician of Felinfoel", "Dewin Felinfoel", "Phil_Bennett", "sport",
   "Fly-half from Felinfoel whose side-steps began the most famous try ever scored, for the Barbarians in 1973, and who captained the Lions.",
   "Maswr o Felinfoel y dechreuodd ei gamau ochr y cais enwocaf a sgoriwyd erioed, i’r Barbariaid yn 1973, ac a fu’n gapten y Llewod.",
   ["Phil Bennett was born in Felinfoel near Llanelli in 1948 and played all his club rugby for Llanelli, the Scarlets, with whom he beat the All Blacks in 1972.",
    "In January 1973, playing for the Barbarians against New Zealand at Cardiff Arms Park, he gathered the ball near his own line and side-stepped three tacklers, starting the move that ended with Gareth Edwards scoring what is often called the greatest try of all time. He won two Grand Slams with Wales and captained the Lions in 1977."],
   ["Ganed Phil Bennett yn Felinfoel ger Llanelli yn 1948 a chwaraeodd ei holl rygbi clwb i Lanelli, y Sgarlets, a gyda hwy curodd y Crysau Duon yn 1972.",
    "Ym mis Ionawr 1973, yn chwarae i’r Barbariaid yn erbyn Seland Newydd ar Barc yr Arfau, Caerdydd, cododd y bêl ger ei linell ei hun a chamu heibio i dri thaclwr, gan ddechrau’r symudiad a orffennodd â Gareth Edwards yn sgorio’r hyn a elwir yn aml y cais gorau erioed. Enillodd ddwy Gamp Lawn gyda Chymru a bu’n gapten y Llewod yn 1977."]),
 P("ian-woosnam", "modern", "born 1958", "Ian Woosnam", "Ian Woosnam", "Woosie", "Woosie", "Ian_Woosnam", "sport",
   "The Welsh golfer who in 1991 became world number one and won the US Masters, the first Welshman to win one of golf’s major championships.",
   "Y golffiwr o Gymro a ddaeth yn rhif un y byd yn 1991 ac a enillodd y Meistri yn yr Unol Daleithiau, y Cymro cyntaf i ennill un o brif bencampwriaethau golff.",
   ["Ian Woosnam grew up on the Welsh border near Oswestry, in a Welsh family, and has always played for Wales. Only five feet four and a half inches tall, he hit the ball as far as anyone in the game.",
    "In April 1991 he became the world number one and won the Masters at Augusta, the first Welshman to win a major championship. He played in eight Ryder Cups and captained Europe to a record-equalling victory in 2006."],
   ["Magwyd Ian Woosnam ar y ffin ger Croesoswallt, mewn teulu Cymreig, ac mae wedi chwarae dros Gymru erioed. Er mai pum troedfedd pedair modfedd a hanner oedd ei daldra, trawai’r bêl cyn belled ag unrhyw un yn y gêm.",
    "Ym mis Ebrill 1991 daeth yn rhif un y byd ac ennill y Meistri yn Augusta, y Cymro cyntaf i ennill un o’r prif bencampwriaethau. Chwaraeodd mewn wyth Cwpan Ryder a bu’n gapten Ewrop i fuddugoliaeth a gyfartalodd y record yn 2006."],
   first=("wales", "The first Welshman to win one of golf’s major championships, 1991", "Y Cymro cyntaf i ennill un o brif bencampwriaethau golff, 1991", 1991)),
 P("neville-southall", "modern", "born 1958", "Neville Southall", "Neville Southall", "The great goalkeeper", "Y gôl-geidwad mawr", "Neville_Southall", "sport",
   "Former binman from Llandudno who became one of the greatest goalkeepers in the world with Everton and won 92 caps for Wales.",
   "Cyn-ddyn bins o Landudno a ddaeth yn un o gôl-geidwaid gorau’r byd gydag Everton ac a enillodd 92 o gapiau dros Gymru.",
   ["Neville Southall was born in Llandudno in 1958 and worked as a binman and a hod carrier while playing for local clubs. Everton signed him in 1981.",
    "In the 1980s he was rated the best goalkeeper in the world, winning the league twice, the FA Cup and the European Cup Winners’ Cup. He won 92 caps for Wales, for many years the national record, and has since become a champion of young people and mental health."],
   ["Ganed Neville Southall yn Llandudno yn 1958 a gweithiodd yn ddyn bins ac yn gludwr briciau wrth chwarae i glybiau lleol. Arwyddodd Everton ef yn 1981.",
    "Yn y 1980au fe’i cyfrifid yn gôl-geidwad gorau’r byd, gan ennill y gynghrair ddwywaith, Cwpan yr FA a Chwpan Enillwyr Cwpanau Ewrop. Enillodd 92 o gapiau dros Gymru, record genedlaethol am flynyddoedd lawer, ac mae wedi dod yn hyrwyddwr pobl ifanc ac iechyd meddwl."]),
 P("ian-rush", "modern", "born 1961", "Ian Rush", "Ian Rush", "Goal machine", "Peiriant goliau", "Ian_Rush", "sport",
   "Striker from Flint who scored 346 goals for Liverpool, a club record, and was Wales’s record goalscorer for over twenty years.",
   "Ymosodwr o’r Fflint a sgoriodd 346 o goliau i Lerpwl, record y clwb, ac a fu’n brif sgoriwr Cymru am dros ugain mlynedd.",
   ["Ian Rush was born in St Asaph in 1961 and grew up in Flint, one of ten children. He joined Liverpool from Chester in 1980 and formed a famous partnership with Kenny Dalglish.",
    "He scored 346 goals for Liverpool, still the club record, won five league titles and the European Cup, and in 1984 won the Golden Boot as the top scorer in Europe. His 28 goals for Wales stood as the national record until Gareth Bale passed it in 2018."],
   ["Ganed Ian Rush yn Llanelwy yn 1961 a’i fagu yn y Fflint, yn un o ddeg o blant. Ymunodd â Lerpwl o Gaer yn 1980 a ffurfio partneriaeth enwog gyda Kenny Dalglish.",
    "Sgoriodd 346 o goliau i Lerpwl, record y clwb o hyd, enillodd bum teitl cynghrair a Chwpan Ewrop, ac yn 1984 enillodd yr Esgid Aur fel prif sgoriwr Ewrop. Safodd ei 28 gôl dros Gymru’n record genedlaethol nes i Gareth Bale ei thorri yn 2018."]),
 P("colin-jackson", "modern", "born 1967", "Colin Jackson", "Colin Jackson", "World champion hurdler", "Pencampwr clwydi’r byd", "Colin_Jackson", "sport",
   "Cardiff hurdler who set a world record of 12.91 seconds in 1993 that stood for thirteen years, and was twice world champion.",
   "Rhedwr clwydi o Gaerdydd a osododd record byd o 12.91 eiliad yn 1993 a safodd am dair blynedd ar ddeg, ac a fu’n bencampwr y byd ddwywaith.",
   ["Colin Jackson was born in Cardiff in 1967 to parents from Jamaica, and went to Llanedeyrn High School. He was a natural all-round athlete and chose the 110 metres hurdles.",
    "At the World Championships in Stuttgart in 1993 he won gold in 12.91 seconds, a world record that stood for thirteen years. He was world champion again in 1999, won Commonwealth and European titles many times and an Olympic silver, and set an indoor world record over 60 metres hurdles that lasted twenty-seven years."],
   ["Ganed Colin Jackson yng Nghaerdydd yn 1967 i rieni o Jamaica, ac aeth i Ysgol Uwchradd Llanedeyrn. Roedd yn athletwr amryddawn naturiol a dewisodd y 110 metr dros y clwydi.",
    "Ym Mhencampwriaethau’r Byd yn Stuttgart yn 1993 enillodd aur mewn 12.91 eiliad, record byd a safodd am dair blynedd ar ddeg. Bu’n bencampwr y byd eto yn 1999, ennill teitlau’r Gymanwlad ac Ewrop lawer gwaith a medal arian Olympaidd, a gosod record byd dan do dros 60 metr clwydi a barodd saith mlynedd ar hugain."],
   first=("world", "World record holder, 110 metres hurdles, 1993–2006", "Deiliad record y byd, 110 metr clwydi, 1993–2006", 1993)),
 P("joe-calzaghe", "today", "born 1972", "Joe Calzaghe", "Joe Calzaghe", "The Pride of Wales", "Balchder Cymru", "Joe_Calzaghe", "sport",
   "Boxer from Newbridge who retired undefeated after 46 fights, world champion for over ten years.",
   "Paffiwr o Drecelyn a ymddeolodd heb ei guro ar ôl 46 gornest, yn bencampwr y byd am dros ddeng mlynedd.",
   ["Joe Calzaghe grew up in Newbridge in Gwent, trained all his career by his father Enzo in a small gym in the valley. He won the world super-middleweight title in 1997 and defended it for more than ten years.",
    "In 2007 he beat Mikkel Kessler before fifty thousand people in Cardiff to unify the titles, and in 2008 he beat Bernard Hopkins and Roy Jones Jr in the United States. He retired in 2009 with a perfect record of 46 wins from 46 fights, one of the few world champions ever to retire undefeated."],
   ["Magwyd Joe Calzaghe yn Nhrecelyn yng Ngwent, a’i hyfforddi drwy gydol ei yrfa gan ei dad Enzo mewn campfa fach yn y cwm. Enillodd deitl uwch-ganol pwysau’r byd yn 1997 a’i amddiffyn am dros ddeng mlynedd.",
    "Yn 2007 curodd Mikkel Kessler o flaen hanner can mil o bobl yng Nghaerdydd i uno’r teitlau, ac yn 2008 curodd Bernard Hopkins a Roy Jones Jr yn yr Unol Daleithiau. Ymddeolodd yn 2009 gyda record berffaith o 46 buddugoliaeth o 46 gornest, un o’r ychydig bencampwyr byd erioed i ymddeol heb eu curo."]),
 P("shane-williams", "today", "born 1977", "Shane Williams", "Shane Williams", "The little magician", "Y dewin bach", "Shane_Williams", "sport",
   "Wing from the Amman valley who scored 58 tries for Wales and was named World Rugby Player of the Year in 2008.",
   "Asgellwr o Ddyffryn Aman a sgoriodd 58 o geisiau dros Gymru ac a enwyd yn Chwaraewr Rygbi’r Byd y Flwyddyn yn 2008.",
   ["Shane Williams was born in Morriston in 1977 and grew up in Glanaman. At five feet seven he was told he was too small for international rugby, and proved everyone wrong with his side-step and speed.",
    "He won two Grand Slams with Wales, in 2005 and 2008, scored 58 tries for his country, the Welsh record, and in 2008 was named World Rugby Player of the Year, the first Welshman to win the award. He played for the Lions in 2005 and 2009."],
   ["Ganed Shane Williams yn Nhreforys yn 1977 a’i fagu yng Nglanaman. Yn bum troedfedd saith dywedwyd wrtho ei fod yn rhy fach i rygbi rhyngwladol, a phrofodd fod pawb yn anghywir â’i gamau ochr a’i gyflymder.",
    "Enillodd ddwy Gamp Lawn gyda Chymru, yn 2005 a 2008, sgoriodd 58 o geisiau dros ei wlad, record Cymru, ac yn 2008 fe’i henwyd yn Chwaraewr Rygbi’r Byd y Flwyddyn, y Cymro cyntaf i ennill y wobr. Chwaraeodd i’r Llewod yn 2005 a 2009."],
   first=("wales", "The first Welshman named World Rugby Player of the Year, 2008", "Y Cymro cyntaf i’w enwi’n Chwaraewr Rygbi’r Byd y Flwyddyn, 2008", 2008)),
 P("nicole-cooke", "today", "born 1983", "Nicole Cooke", "Nicole Cooke", "Olympic and world road champion", "Pencampwraig ffordd Olympaidd a’r byd", "Nicole_Cooke", "sport",
   "Cyclist from Wick in the Vale of Glamorgan who in 2008 became the first rider ever to win the Olympic and world road race titles in the same year.",
   "Seiclwraig o’r Wig ym Mro Morgannwg a ddaeth, yn 2008, y reidiwr cyntaf erioed i ennill teitlau ras ffordd Olympaidd a’r byd yn yr un flwyddyn.",
   ["Nicole Cooke grew up in Wick in the Vale of Glamorgan and was winning national titles against adults while still at school. She won the Giro d’Italia and the Tour de France for women.",
    "On a rainy day in Beijing in August 2008 she won the Olympic road race, Britain’s first gold of those Games. A month later she won the world road race championship in Italy, the first rider, man or woman, ever to hold both titles in the same year."],
   ["Magwyd Nicole Cooke yn y Wig ym Mro Morgannwg ac roedd yn ennill teitlau cenedlaethol yn erbyn oedolion tra oedd yn dal yn yr ysgol. Enillodd y Giro d’Italia a’r Tour de France i fenywod.",
    "Ar ddiwrnod glawog yn Beijing yn Awst 2008 enillodd y ras ffordd Olympaidd, medal aur gyntaf Prydain yn y Gemau hynny. Fis yn ddiweddarach enillodd bencampwriaeth ras ffordd y byd yn yr Eidal, y reidiwr cyntaf, yn ddyn neu’n fenyw, erioed i ddal y ddau deitl yn yr un flwyddyn."],
   first=("world", "The first rider ever to win Olympic and world road race titles in the same year, 2008", "Y reidiwr cyntaf erioed i ennill teitlau ras ffordd Olympaidd a’r byd yn yr un flwyddyn, 2008", 2008)),
 P("alun-wyn-jones", "today", "born 1985", "Alun Wyn Jones", "Alun Wyn Jones", "Most capped player in rugby history", "Y chwaraewr â’r mwyaf o gapiau yn hanes rygbi", "Alun_Wyn_Jones", "sport",
   "Swansea lock who captained Wales to Grand Slams and the Lions in South Africa, and played more Test matches than anyone in rugby history.",
   "Clo o Abertawe a fu’n gapten Cymru i Gampau Llawn a’r Llewod yn Ne Affrica, ac a chwaraeodd fwy o gemau prawf nag unrhyw un yn hanes rygbi.",
   ["Alun Wyn Jones was born in Swansea in 1985 and first played for Wales in 2006. A tireless, fearless lock forward, he won three Grand Slams, in 2008, 2012 and 2019, and the Six Nations again in 2013 and 2021, and captained his country in a World Cup semi-final.",
    "He toured with the Lions four times and captained them in South Africa in 2021. By the time he retired in 2024 he had played 158 Tests for Wales and 12 for the Lions, 170 in all, more than any player in the history of the game."],
   ["Ganed Alun Wyn Jones yn Abertawe yn 1985 a chwaraeodd i Gymru gyntaf yn 2006. Yn glo diflino, di-ofn, enillodd y Gamp Lawn dair gwaith, yn 2008, 2012 a 2019, a theitl y Chwe Gwlad yn 2013 a 2021, a bu’n gapten ei wlad mewn rownd gynderfynol Cwpan y Byd.",
    "Teithiodd gyda’r Llewod bedair gwaith a bu’n gapten arnynt yn Ne Affrica yn 2021. Erbyn iddo ymddeol yn 2024 roedd wedi chwarae 158 o gemau prawf dros Gymru a 12 i’r Llewod, 170 i gyd, mwy nag unrhyw chwaraewr yn hanes y gêm."],
   first=("world", "The most capped player in the history of rugby union: 170 Tests", "Y chwaraewr â’r mwyaf o gapiau yn hanes rygbi’r undeb: 170 o gemau prawf", 2024)),
 P("geraint-thomas", "today", "born 1986", "Geraint Thomas", "Geraint Thomas", "Winner of the Tour de France", "Enillydd y Tour de France", "Geraint_Thomas", "sport",
   "Cyclist from Birchgrove in Cardiff who won two Olympic gold medals on the track and, in 2018, the Tour de France.",
   "Seiclwr o Birchgrove yng Nghaerdydd a enillodd ddwy fedal aur Olympaidd ar y trac ac, yn 2018, y Tour de France.",
   ["Geraint Thomas was born in Cardiff in 1986 and learned to race with the Maindy Flyers club. He won Olympic gold in the team pursuit in Beijing in 2008 and again in London in 2012.",
    "Moving to road racing, on 29 July 2018 he rode into Paris wearing the yellow jersey as winner of the Tour de France, the first Welshman ever to win it, and he crossed the line with a Welsh flag. Cardiff welcomed him home with a celebration in front of the castle."],
   ["Ganed Geraint Thomas yng Nghaerdydd yn 1986 a dysgodd rasio gyda chlwb Maindy Flyers. Enillodd aur Olympaidd yn y ras ymlid tîm yn Beijing yn 2008 ac eto yn Llundain yn 2012.",
    "Gan droi at rasio ffordd, ar 29 Gorffennaf 2018 reidiodd i mewn i Baris yn y crys melyn fel enillydd y Tour de France, y Cymro cyntaf erioed i’w hennill, a chroesodd y llinell gyda draig goch. Croesawodd Caerdydd ef adref â dathliad o flaen y castell."],
   first=("wales", "The first Welshman to win the Tour de France, 2018", "Y Cymro cyntaf i ennill y Tour de France, 2018", 2018)),
 P("gareth-bale", "today", "born 1989", "Gareth Bale", "Gareth Bale", "Wales’s greatest footballer", "Pêl-droediwr mwyaf Cymru", "Gareth_Bale", "sport",
   "Cardiff-born winger who won five Champions Leagues with Real Madrid and led Wales to the semi-finals of Euro 2016 and the 2022 World Cup.",
   "Asgellwr o Gaerdydd a enillodd bum Cynghrair y Pencampwyr gyda Real Madrid ac a arweiniodd Gymru i rownd gynderfynol Ewro 2016 a Chwpan y Byd 2022.",
   ["Gareth Bale was born in Cardiff in 1989 and went to Whitchurch High School. He moved from Southampton to Tottenham and then, in 2013, to Real Madrid for a world-record fee.",
    "He won five Champions Leagues in Madrid, scoring an overhead kick in the 2018 final. For Wales he scored a record 41 goals, led the team to the semi-finals of Euro 2016, and in 2022 took Wales to their first World Cup since 1958, where he scored their first goal at the finals in sixty-four years."],
   ["Ganed Gareth Bale yng Nghaerdydd yn 1989 ac aeth i Ysgol Uwchradd yr Eglwys Newydd. Symudodd o Southampton i Tottenham ac yna, yn 2013, i Real Madrid am ffi a oedd yn record byd.",
    "Enillodd bum Cynghrair y Pencampwyr ym Madrid, gan sgorio cic siswrn yn rownd derfynol 2018. Dros Gymru sgoriodd record o 41 gôl, arwain y tîm i rownd gynderfynol Ewro 2016, ac yn 2022 aeth â Chymru i’w Chwpan y Byd cyntaf ers 1958, lle sgoriodd ei gôl gyntaf yn y rowndiau terfynol ers pedair blynedd a thrigain."]),
 P("jade-jones", "today", "born 1993", "Jade Jones", "Jade Jones", "The Headhunter", "Yr Heliwr Pennau", "Jade_Jones", "sport",
   "Taekwondo fighter from Flint who won Olympic gold in 2012 and 2016, the first British taekwondo champion and the first to win twice.",
   "Ymladdwraig taekwondo o’r Fflint a enillodd aur Olympaidd yn 2012 a 2016, pencampwr taekwondo cyntaf Prydain a’r cyntaf i ennill ddwywaith.",
   ["Jade Jones was born in Bodelwyddan in 1993 and grew up in Flint, where her grandfather took her to taekwondo classes to keep her out of trouble. Her fighting style, all attack and high kicks, earned her the nickname the Headhunter.",
    "At the London Olympics in 2012, aged nineteen, she won Britain’s first ever Olympic gold in taekwondo, and in Rio in 2016 she won again, the first British fighter to defend the title. Flint gave her a postbox painted gold."],
   ["Ganed Jade Jones ym Modelwyddan yn 1993 a’i magu yn y Fflint, lle aeth ei thaid â hi i ddosbarthiadau taekwondo i’w chadw allan o drwbl. Enillodd ei steil ymladd, yn ymosod o hyd ac yn cicio’n uchel, y llysenw’r Heliwr Pennau iddi.",
    "Yng Ngemau Olympaidd Llundain yn 2012, yn bedair ar bymtheg oed, enillodd fedal aur Olympaidd gyntaf erioed Prydain mewn taekwondo, ac yn Rio yn 2016 enillodd eto, yr ymladdwr cyntaf o Brydain i amddiffyn y teitl. Rhoddodd y Fflint flwch post wedi’i beintio’n aur iddi."],
   first=("wales", "Britain’s first Olympic taekwondo champion, 2012, and the first to win twice, 2016", "Pencampwr taekwondo Olympaidd cyntaf Prydain, 2012, a’r cyntaf i ennill ddwywaith, 2016", 2012)),
 P("lauren-price", "today", "born 1994", "Lauren Price", "Lauren Price", "Olympic and world champion boxer", "Pencampwraig focsio Olympaidd a’r byd", "Lauren_Price", "sport",
   "From Ystrad Mynach, a footballer for Wales and kickboxing world champion who won Olympic boxing gold in Tokyo and became a professional world champion.",
   "O Ystrad Mynach; pêl-droedwraig dros Gymru a phencampwraig cic-focsio’r byd a enillodd aur bocsio Olympaidd yn Tokyo ac a ddaeth yn bencampwraig byd broffesiynol.",
   ["Lauren Price was raised in Ystrad Mynach by her grandparents, who backed every sport she tried. She played football for Wales, won world titles in kickboxing as a teenager and then turned to boxing.",
    "In 2021 at the Tokyo Olympics she won gold at middleweight, the first Welsh woman to win Olympic boxing gold. She turned professional and became world welterweight champion, carrying the Welsh flag into every fight."],
   ["Magwyd Lauren Price yn Ystrad Mynach gan ei nain a’i thaid, a gefnogai bob camp a fentrai. Chwaraeodd bêl-droed dros Gymru, enillodd deitlau byd mewn cic-focsio yn ei harddegau ac yna troi at focsio.",
    "Yn 2021 yng Ngemau Olympaidd Tokyo enillodd aur ar bwysau canol, y fenyw gyntaf o Gymru i ennill aur bocsio Olympaidd. Trodd yn broffesiynol a dod yn bencampwraig pwysau welter y byd, gan gario’r ddraig goch i bob gornest."],
   first=("wales", "The first Welsh woman to win Olympic boxing gold, 2021", "Y fenyw gyntaf o Gymru i ennill aur bocsio Olympaidd, 2021", 2021)),
]
